    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.u32 %r1, [total];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.s32 %r5, %r2, %r3, %r4;

    setp.ge.s32 %p1, %r5, %r1;
    @%p1 bra DONE;

    div.s32 %r6, %r5, 222;
    rem.s32 %r7, %r5, 222;
    div.s32 %r8, %r6, 222;
    rem.s32 %r9, %r6, 222;
    div.s32 %r10, %r8, 32;
    rem.s32 %r11, %r8, 32;

    mov.f32 %f1, 0f00000000;

    mul.lo.s32 %r12, %r10, 150528;
    mul.lo.s32 %r13, %r11, 27;

    mov.s32 %r20, 0;
IC_LOOP:
    mov.s32 %r21, 0;
KH_LOOP:
    mov.s32 %r22, 0;
KW_LOOP:
    add.s32 %r23, %r9, %r21;
    add.s32 %r24, %r7, %r22;

    mul.lo.s32 %r25, %r20, 50176;
    add.s32 %r25, %r12, %r25;
    mul.lo.s32 %r26, %r23, 224;
    add.s32 %r25, %r25, %r26;
    add.s32 %r25, %r25, %r24;

    mul.lo.s32 %r27, %r20, 9;
    add.s32 %r27, %r13, %r27;
    mul.lo.s32 %r28, %r21, 3;
    add.s32 %r27, %r27, %r28;
    add.s32 %r27, %r27, %r22;

    mul.wide.s32 %rd10, %r25, 2;
    add.s64 %rd11, %rd1, %rd10;
    ld.global.u16 %rs1, [%rd11];
    cvt.f32.bf16 %f2, %rs1;

    mul.wide.s32 %rd12, %r27, 2;
    add.s64 %rd13, %rd2, %rd12;
    ld.global.u16 %rs2, [%rd13];
    cvt.f32.bf16 %f3, %rs2;

    fma.rn.f32 %f1, %f2, %f3, %f1;

    add.s32 %r22, %r22, 1;
    setp.lt.s32 %p2, %r22, 3;
    @%p2 bra KW_LOOP;

    add.s32 %r21, %r21, 1;
    setp.lt.s32 %p3, %r21, 3;
    @%p3 bra KH_LOOP;

    add.s32 %r20, %r20, 1;
    setp.lt.s32 %p4, %r20, 3;
    @%p4 bra IC_LOOP;

    cvt.rn.bf16.f32 %rs3, %f1;
    mul.wide.s32 %rd14, %r5, 2;
    add.s64 %rd15, %rd3, %rd14;
    st.global.u16 [%rd15], %rs3;

DONE:
    ret;
}
