_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv2d_bf16")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=32, kernel_size=3, bias=False, dtype=torch.bfloat16)

    def forward(self, x):
        x = x.contiguous()
        weight = self.conv1.weight.contiguous()

        N, C, H, W = x.shape
        OC = weight.shape[0]
        OH = H - 2
        OW = W - 2

        out = torch.empty((N, OC, OH, OW), dtype=torch.bfloat16, device=x.device)

        total = N * OC * OH * OW
        block = 256
        grid = (total + block - 1) // block

        module = _get_ptx_module()
        module.launch(
            "conv2d_bf16",
            grid=(grid, 1, 1),
            block=(block, 1, 1),
            arguments=[x, weight, out, i32(total)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return out

